using Microsoft.EntityFrameworkCore;
using Mladim.Domain.Enums;
using Mladim.Domain.Models;
using Mladim.Domain.Models.Survey.Questions;

namespace Mladim.Infrastracture.Persistance;

public static class SurveyQuestionSeeder
{
    public static async Task SeedAsync(ApplicationDbContext context)
    {      

        await context.Questions.ExecuteDeleteAsync();
        await context.Database.ExecuteSqlRawAsync("DBCC CHECKIDENT ('[Questions]', RESEED, 0);");        

        var questions = new List<SurveyQuestion>
        {
            // participants 1..7 (Ids will be DB-generated by EF)
            SurveyQuestion.ForParticipant(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Počutila sem se varno in prijetno.","Počutil sem se varno in prijetno.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Bila sem slišana in sprejeta.","Bil sem slišan in sprejet.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Sodelovala sem pri načrtovanju ali izvedbi te aktivnosti/dogodka","Sodeloval sem pri načrtovanju ali izvedbi te aktivnosti/dogodka")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Spodbujena sem bila k aktivni udeležbi.","Spodbujen sem bil k aktivni udeležbi.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Z aktivnostjo sem bila zadovoljna.","Z aktivnostjo sem bil zadovoljen.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Text, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Z eno ali nekaj besedami opiši, kaj si z udeležbo pridobila.","Z eno ali nekaj besedami opiši, kaj si z udeležbo pridobil.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Ali si zaradi svojih telesnih značilnosti, socialnega položaja, narodnosti ali barve kože v slabšem položaju kot večina ostalih?")),

            // group 8..10
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.Group)
                .AddQuestion(GenderText.SameText("Cilji, zaradi katerih smo delovali v skupini, so mi bili jasni.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Rating, SurveyQuestionCategory.Group)
                .AddQuestion(new GenderText("Sodelovala sem pri oblikovanju ciljev skupine in skupinskega dela.","Sodeloval sem pri oblikovanju ciljev skupine in skupinskega dela.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.Group)
                .AddQuestion(new GenderText("Moja pričakovanja, ki sem jih imela od sodelovanja v skupini, so bila jasna in znana drugim (npr.mentorju.)","Moja pričakovanja, ki sem jih imel od sodelovanja v skupini, so bila jasna in znana drugim (npr.mentorju.)")),

            // parent 11 with owned subquestions
            SurveyQuestion.ForParticipant(SurveyQuestionType.Multiple, SurveyQuestionCategory.Group, GenderText.SameText("Zaradi sodelovanja v aktivnosti sem:"))
                .AddQuestion(new GenderText("bolj samozavestna", "bolj samozavesten"))
                .AddQuestion(new GenderText("bolj sposobna delati v skupini", "bolj sposoben delati v skupini"))
                .AddQuestion(GenderText.SameText("se je izboljšal moj učni uspeh"))
                .AddQuestion(GenderText.SameText("lažje branim svoje mnenje"))
                .AddQuestion(GenderText.SameText("verjamem, da je skupaj mogoče doseči pomembne spremembe")),

            // parents 12..15
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.Group)
