            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.Group)
                .AddQuestion(GenderText.SameText("Mentor je vzpostavil varen in vključujoč prostor.")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Boolean, SurveyQuestionCategory.Group)
                .AddQuestion(GenderText.SameText("Moja skupina se je redno srečevala (vsaj dvakrat mesečno).")),
            SurveyQuestion.ForParticipant(SurveyQuestionType.Rating, SurveyQuestionCategory.Group)
                .AddQuestion(GenderText.SameText("V skupini smo poleg vsebinskih aktivnosti izvajali tudi aktivnosti, ki so krepile skupino (npr. teambuilding ipd.)")),

            // parent 16 (repetitive) with owned subquestions
            SurveyQuestion.ForParticipant(SurveyQuestionType.MultipleRepetitive, SurveyQuestionCategory.Repetitive, new GenderText("V kolikšni meri si zaradi udeležbe okrepila naslednje sposobnosti:","V kolikšni meri si zaradi udeležbe okrepil naslednje sposobnosti:"))
                .AddQuestion(new GenderText("Sposobna sem se uspešno sporazumevati in povezovati z drugimi.", "Sposoben sem se uspešno sporazumevati in povezovati z drugimi."))
                .AddQuestion(new GenderText("Sposobna sem ustrezno uporabljati različne jezike za sporazumevanje z drugimi.", "Sposoben sem ustrezno uporabljati različne jezike za sporazumevanje z drugimi."))
                .AddQuestion(new GenderText("Sposobna sem uporabljati matematično znanje za reševanje vsakodnevnih izzivov.", "Sposoben sem uporabljati matematično znanje za reševanje vsakodnevnih izzivov."))
                .AddQuestion(new GenderText("Sposobna sem kompetentno uporabljati digitalna orodja pri delu, učenju in stikih z drugimi.", "Sposoben sem kompetentno uporabljati digitalna orodja pri delu, učenju in stikih z drugimi."))
                .AddQuestion(new GenderText("Sposobna sem ohranjati dobro psihično in fizično počutje ter dobre stike z drugimi.", "Sposoben sem ohranjati dobro psihično in fizično počutje ter dobre stike z drugimi."))
                .AddQuestion(new GenderText("Sposobna sem oceniti svoje šibke točke ter tudi pridobiti novo znanje, s katerim jih nadomestim.", "Sposoben sem oceniti svoje šibke točke ter tudi pridobiti novo znanje, s katerim jih nadomestim."))
                .AddQuestion(new GenderText("Sposobna sem delovati kot odgovoren državljan in se polno udeleževati v družbeno in politično življenje.", "Sposoben sem delovati kot odgovoren državljan in se polno udeleževati v družbeno in politično življenje."))
                .AddQuestion(new GenderText("Sposobna sem delovati podjetno in izkoristiti priložnosti, ki se mi ponujajo.", "Sposoben sem delovati podjetno in izkoristiti priložnosti, ki mi ponujajo."))
                .AddQuestion(new GenderText("Odprta sem do različnih kultur in njihovih običajev ter jih tudi spoštujem.", "Odprt sem do različnih kultur in njihovih običajev ter jih tudi spoštujem.")),

            // youth worker parents 17..28
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Z aktivnostjo sem bila zadovoljna.","Z aktivnostjo sem bil zadovoljen.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Vsebine aktivnosti so bile kakovostne.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(new GenderText("Pridobila sem novo znanje, veščine ali vpoglede v mladinsko delo.","Pridobil sem novo znanje, veščine ali vpoglede v mladinsko delo.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Vsebine so bile relevantne za mojo prakso mladinskega dela.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Vsebine so me inspirirale za kakovostno mladinsko delo in delo z mladimi.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Vsebine so me motivirale za nadaljnje delo z mladimi in za mladinsko delo.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Pridobljena znanja, metode ali orodja nameravam uporabiti pri svojem delu in v organizaciji, v kateri delujem.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Text, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Kako je nate vplivala aktivnost in kakšne so spremembe pri tvojem delu zaradi te aktivnosti?")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Text, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Kaj nameravaš zaradi te aktivnosti pri svojem delu narediti drugače ali na novo?")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Text, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Pri katerem delu svojega dela ste uporabili svoja pridobljena znanja?")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Text, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Na kratko opiši, kaj te je (de)motiviralo pri sodelovanju v aktivnosti.")),
            SurveyQuestion.ForYouthWorker(SurveyQuestionType.Rating, SurveyQuestionCategory.General)
                .AddQuestion(GenderText.SameText("Metode dela in podporna orodja (gradiva, materiali) so podpirala moje učenje."))
        };        

        context.Questions.AddRange(questions);
        await context.SaveChangesAsync();
    }
}